import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type RainbowMountainsProps = Record<string, any>;

const RAINBOW_COLORS = [
  "#FF0000", // Red
  "#FF7F00", // Orange
  "#FFFF00", // Yellow
  "#00FF00", // Green
  "#0000FF", // Blue
  "#4B0082", // Indigo
  "#9400D3", // Violet
];

const RainbowMountains: React.FC<RainbowMountainsProps> = ({
  backgroundColor = "#87CEEB",
  transparentBackground = false,
  durationInSeconds = 8,
  mountainFrontColor = "#2d4a3e",
  mountainBackColor = "#1a2f26",
  sunColor = "#FFD700",
  rainbowOpacity = 0.8,
  mountainPeakHeight = 0.6,
}) => {
  useFontLoader(["Nunito"]); // Loaded for structure compliance

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // --- Parsing & Logic ---
  const finalBgColor = transparentBackground
    ? `${backgroundColor}00` // transparent hex
    : backgroundColor;

  // --- Animation Drivers ---

  // 1. Mountains Rise (Spring)
  const mountainSpring = spring({
    frame: frame - 10,
    fps,
    config: { damping: 12, stiffness: 100 },
  });

  // 2. Sun Rise (Spring with delay)
  const sunRise = spring({
    frame: frame - 20,
    fps,
    config: { damping: 15, stiffness: 80 },
  });

  // 3. Rainbow Reveal (Staggered Interpolation)
  // We animate strokeDashoffset from Length to 0
  
  // --- Geometry Calculations ---
  
  // Sun position
  const sunRadius = width * 0.08;
  const sunCyStart = height + sunRadius; // Start below screen
  const sunCyEnd = height * 0.2;
  const sunCy = interpolate(sunRise, [0, 1], [sunCyStart, sunCyEnd]);

  // Mountains
  // Peak Y calculation based on slider (inverted because 0 is top)
  const peakY = height * (1 - mountainPeakHeight);
  const valleyY = height;

  // Create Mountain Paths
  // Back Mountain: Center-Right
  const backMtnPath = `
    M ${width * -0.1} ${valleyY}
    L ${width * 0.6} ${peakY * 1.1} 
    L ${width * 1.2} ${valleyY} 
    Z
  `;

  // Front Mountain: Center-Left
  const frontMtnPath = `
    M ${width * -0.2} ${valleyY}
    L ${width * 0.35} ${peakY} 
    L ${width * 1.1} ${valleyY} 
    Z
  `;

  // Rainbow Geometry
  // Centered horizontally, arcing over the mountains
  const rainbowCenter = { x: width / 2, y: height * 0.85 }; // Lower down so it looks like it's behind mountains
  const baseRadius = width * 0.3;
  const strokeWidth = width * 0.03;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: finalBgColor,
        fontFamily: "Nunito",
        overflow: "hidden",
      }}
    >
      <svg
        width={width}
        height={height}
        viewBox={`0 0 ${width} ${height}`}
        style={{ overflow: "visible" }}
      >
        {/* --- SUN --- */}
        <circle
          cx={width * 0.8}
          cy={sunCy}
          r={sunRadius}
          fill={sunColor}
          opacity={interpolate(sunRise, [0, 0.5], [0, 1])}
          style={{ transition: "none" }}
        />

        {/* --- RAINBOW --- */}
        <g style={{ opacity: rainbowOpacity, transition: "none" }}>
          {RAINBOW_COLORS.map((color, index) => {
            // Reverse index for layering: Outer (red) first? No, SVG draws painter's algo.
            // We want Red on top (outermost)? Usually Red is top.
            // Let's draw largest radius first (Red) to smallest (Violet) if filled, 
            // but these are strokes, so order matters less for occlusion, just visuals.
            // Standard rainbow: Red is outer.
            
            const bandRadius = baseRadius + (RAINBOW_COLORS.length - 1 - index) * strokeWidth;
            const arcLength = Math.PI * bandRadius;
            
            // Stagger the animation
            const startFrame = 30 + index * 4;
            const progress = interpolate(
              frame,
              [startFrame, startFrame + 45],
              [0, 1],
              { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
            );
            
            // Calculate dash offset: from arcLength (hidden) to 0 (shown)
            const dashOffset = interpolate(progress, [0, 1], [arcLength, 0]);

            return (
              <path
                key={color}
                d={`
                  M ${rainbowCenter.x - bandRadius} ${rainbowCenter.y}
                  A ${bandRadius} ${bandRadius} 0 0 1 ${rainbowCenter.x + bandRadius} ${rainbowCenter.y}
                `}
                fill="none"
                stroke={color}
                strokeWidth={strokeWidth}
                strokeLinecap="round"
                strokeDasharray={arcLength}
                strokeDashoffset={dashOffset}
                style={{ transition: "none" }}
              />
            );
          })}
        </g>

        {/* --- MOUNTAINS --- */}
        {/* Back Mountain */}
        <path
          d={backMtnPath}
          fill={mountainBackColor}
          style={{
            transformOrigin: "bottom center",
            transform: `scaleY(${mountainSpring})`,
            transition: "none",
          }}
        />

        {/* Front Mountain */}
        <path
          d={frontMtnPath}
          fill={mountainFrontColor}
          style={{
            transformOrigin: "bottom center",
            transform: `scaleY(${mountainSpring})`,
            transition: "none",
          }}
        />
      </svg>
    </AbsoluteFill>
  );
};

export default RainbowMountains;